下面代码输出什么？
try:
    print(1/0)
except:
    print('错了')

下面代码输出什么？
try:
    int('abc')
except ValueError:
    print('类型错误')

执行下面的代码，输出什么？
try:
    print(10 / 0)
except:
    print('error')

执行下面的代码，输出什么？
try:
    int('99')
except:
    print('错')
else:
    print('对')

下面代码输出什么？
def deco(f):
    def wrap():
        return f() + 1
    return wrap
def num():
    return 10
num = deco(num)
print(num())

执行下面的代码，输出什么？
def deco(f):
    def wrap():
        return f() * 2
    return wrap
def n():
    return 5
n = deco(n)
print(n())

执行下面的代码，输出什么？
def deco(f):
    def wrap():
        print('start')
        f()
    return wrap
def hi():
    print('hi')
hi = deco(hi)
hi()

执行下面的代码，输出什么？
def deco(f):
    def wrap():
        return f() + 100
    return wrap
def get():
    return 1
get = deco(get)
print(get())

下面代码输出什么？
def deco(f):
    def wrap():
        return f() + 1
    return wrap
@deco
def n():
    return 5
print(n())

